// These views use only backend-authorized data. Permissions are enforced again by the API.
export function programPanel(tab,{data,admin,day,escapeHTML:e,heading,renderGroups,query=''}) {
  query=query.trim().toLowerCase();
  const students=data.students.filter(s=>s.active && (s.name+' '+s.grade+' '+(s.group_name??'')).toLowerCase().includes(query));
  function eventGroups(events, key, renderEvent) {
    if (!events.length) return '';
    const members=[...new Map(events.map(event=>{
      const student=data.students.find(s=>s.id===event.student);
      return [event.student,{...student,id:event.student,name:event.student_name??student?.name??('Student '+event.student)}];
    })).values()].filter(s=>!query||(s.name+' '+(s.group_name??'')).toLowerCase().includes(query));
    if(!members.length)return '<p class="empty">No records match this search.</p>';
    return renderGroups(members,key,students=>students.map(s=>`<details class="student-editor" data-manage-key="${key}-student-${s.id}"><summary class="student-summary">${e(s.name)}</summary>${events.filter(event=>event.student===s.id).map(renderEvent).join('')}</details>`).join(''));
  }
  const chooseStudent=`<label>Student<select name="student" required><option value="">Choose a student</option>${[...new Map(students.map(s=>[s.group_id??'unassigned',s.group_name??'Unassigned students']))].map(([id,name])=>`<optgroup label="${e(name)}">${students.filter(s=>(s.group_id??'unassigned')===id).map(s=>`<option value="${s.id}">${e(s.name)}</option>`).join('')}</optgroup>`).join('')}</select></label>`;
  if(tab==='incidents')return heading('Incidents','Teachers see their own reports; administrators review all reports.')+
    `<div class="entry"><form data-form="incident">${chooseStudent}<label>Category<select name="category"><option>Injury</option><option>Behavior</option><option>Safety</option><option>Other</option></select></label><label>What happened<textarea name="detail" maxlength="2000" required></textarea></label><label>Action taken<textarea name="actionTaken" maxlength="2000" required></textarea></label><button class="primary">Record incident</button></form></div>`+
    (data.incidents.length?eventGroups(data.incidents,'incidents',i=>`<article class="entry"><h3>${e(i.student_name)} · ${e(i.category)}</h3><p>${e(i.detail)}</p><p>Action: ${e(i.action_taken)}</p><p class="muted">${e(i.recorded_by)} · ${e(new Date(i.at).toLocaleString())}</p>${i.resolved_at?`<p>Resolution: ${e(i.resolution)} (${e(i.resolved_by)})</p>`:admin?`<form data-form="resolve-incident"><input name="id" type="hidden" value="${e(i.id)}"><label>Resolution<textarea name="resolution" maxlength="2000" required></textarea></label><button>Resolve incident</button></form>`:'<span class="badge">Open</span>'}</article>`):'<p class="empty">No incident reports for this date.</p>');
  if(tab==='pickup')return heading('Student pickup','Verify identity against the authorized contact before releasing a student.')+
    renderGroups(students,'pickup',members=>members.map(s=>{
      const contacts=data.pickupContacts.filter(c=>c.student===s.id),collected=data.pickups.find(p=>p.student===s.id&&!p.voided_at);
      return `<details class="student-editor" data-manage-key="pickup-student-${s.id}"><summary class="student-summary"><strong>${e(s.name)}</strong><span>Grade ${e(s.grade)}</span><span class="badge">${collected?'Pickup recorded':'No pickup recorded'}</span></summary><div class="student-controls">${admin?`<details><summary>Authorize pickup contact</summary><form data-form="pickup-contact"><input name="student" type="hidden" value="${s.id}"><label>Full name<input name="name" maxlength="120" required></label><label>Relationship<input name="relationship" maxlength="80" required></label><button>Add authorized contact</button></form></details>`:''}${contacts.map(c=>`<p>${e(c.name)} (${e(c.relationship)}) ${admin?`<button data-action="contact-disable" data-id="${e(c.id)}">Revoke authorization</button>`:''}</p>`).join('')||'<p>No authorized pickup contacts.</p>'}${collected?`<p class="badge">Picked up by ${e(collected.contact_name)} at ${e(new Date(collected.at).toLocaleTimeString())}</p>${admin?`<form data-form="void-pickup"><input name="id" type="hidden" value="${e(collected.id)}"><label>Correction reason<input name="reason" maxlength="500" required></label><button>Void mistaken pickup</button></form>`:''}`:contacts.length?`<form data-form="pickup"><input name="student" type="hidden" value="${s.id}"><label>Authorized adult<select name="contact" required><option value="">Choose contact</option>${contacts.map(c=>`<option value="${e(c.id)}">${e(c.name)}</option>`).join('')}</select></label><label>Note<input name="note" maxlength="500"></label><label><input type="checkbox" name="identityChecked" required>Identity checked against authorization</label><button class="primary" ${day===data.today?'':'disabled'}>Record pickup</button></form>`:''}</div></details>`;
    }).join(''))+`<details class="entry" data-manage-key="pickup-audit"><summary>Pickup audit (${data.pickups.length} events)</summary><p>Corrections preserve the original event.</p>`+(eventGroups(data.pickups,'pickup-audit',p=>`<div class="entry"><strong>${e(p.student_name)}</strong> · ${e(p.contact_name)}<p>${e(p.recorded_by)} · ${e(new Date(p.at).toLocaleString())}</p><p>${e(p.note)}</p>${p.voided_at?`<p>Voided: ${e(p.void_reason)} (${e(p.voided_by)})</p>`:''}</div>`)||'<p class="empty">No pickups for this date.</p>')+'</details>';
  if(tab==='reports'&&admin)return heading('Report exports','Exports include archived records. Keep downloaded files private.')+`<div class="entry"><form data-form="export"><label>Report<select name="type">${['attendance','homework','staff','activities','incidents','pickup'].map(t=>`<option>${t}</option>`).join('')}</select></label><label>From<input name="from" type="date" value="${e(day)}" required></label><label>Through<input name="to" type="date" value="${e(day)}" required></label><button class="primary" type="submit" name="format" value="csv">Download CSV</button><button type="submit" name="format" value="pdf">Download PDF</button></form></div>`;
  return null;
}

